INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "郑和", "aliases": ["鄭和"], "era": "明", "birth_year": null, "death_year": null, "description": "明代中官。本纪载其于永乐三年率舟师出使西洋各国。", "biography": null, "status": "draft", "id": "9a24d146-cea1-5746-85e4-479becda6195"}, {"name": "蹇义", "aliases": ["蹇義"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，蹇义出任吏部尚书。", "biography": null, "status": "draft", "id": "9ba158c7-e385-515d-a04d-b17a7bb11a0a"}, {"name": "朱荣", "aliases": ["朱仲华"], "era": "明", "birth_year": null, "death_year": null, "description": "朱荣领兵担任前锋。", "biography": null, "status": "draft", "id": "7c50ae9b-791a-520b-9a9b-f076a35ad63f"}, {"name": "柳升", "aliases": ["安远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "柳升以安远侯身份率领大营。", "biography": null, "status": "draft", "id": "14f79103-5514-5b8a-b46f-74887204ab53"}, {"name": "陈懋", "aliases": ["宁阳侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈懋以宁阳侯身份巡边阅兵。", "biography": null, "status": "draft", "id": "e5696099-627f-57a5-b989-87e71d1b2e68"}, {"name": "郑亨", "aliases": ["武安侯"], "era": "明", "birth_year": null, "death_year": null, "description": "郑亨以武安侯身份率领中军。", "biography": null, "status": "draft", "id": "c500cb31-5132-5a9b-8600-28aa5c7f9ee8"}, {"name": "张辅", "aliases": ["张文弼"], "era": "明", "birth_year": null, "death_year": null, "description": "张辅率军在爱子江交战。", "biography": null, "status": "draft", "id": "ef0d049d-1c37-5697-84d4-4274dfac2d2d"}, {"name": "王通（明代成山侯）", "aliases": ["成山侯"], "era": "明", "birth_year": null, "death_year": null, "description": "王通赴陕西赈济饥民。", "biography": null, "status": "draft", "id": "f94e24e9-3278-51e4-895d-513be2a33e0d"}, {"name": "夏原吉", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，夏原吉出任户部尚书。", "biography": null, "status": "draft", "id": "1f881ca5-40e5-5578-8f0a-653eb82f0a44"}, {"name": "吴中", "aliases": ["吳中"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐2年（年号对照1404年）九月，吴中出任右都御史。", "biography": null, "status": "draft", "id": "322e138f-8e05-53df-89d6-67fa82c7457a"}, {"name": "方宾", "aliases": ["方賓"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐7年（年号对照1409年），方宾以兵部侍郎身份随侍皇帝出行，兼理行在吏部事务。", "biography": null, "status": "draft", "id": "df776bd6-1ecd-59c9-a31b-50b85b5d8cc7"}, {"name": "李时勉", "aliases": ["李懋"], "era": "明", "birth_year": null, "death_year": null, "description": "李时勉以侍读身份被下狱。", "biography": null, "status": "draft", "id": "c925d68f-aef6-5e23-93cb-cd7a19e52416"}, {"name": "李彬", "aliases": ["丰城侯"], "era": "明", "birth_year": null, "death_year": null, "description": "李彬以丰城侯身份率领右哨。", "biography": null, "status": "draft", "id": "04c63363-9652-5acf-9921-b7fbfbf6b56d"}, {"name": "李庆（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐18年（年号对照1420年）十二月，李庆出任工部尚书。", "biography": null, "status": "draft", "id": "71a02ba9-f883-5c28-9f7d-f096e9ad8b22"}, {"name": "阿鲁台", "aliases": ["和宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "阿鲁台受封和宁王。", "biography": null, "status": "draft", "id": "fd6d854f-724b-5621-91d3-593e412f448b"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "杨士奇", "aliases": ["楊士奇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨士奇以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "cf93d13f-f48a-5fc6-8687-47933c0ca559"}, {"name": "吕震（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐3年（年号对照1405年）九月，吕震出任刑部尚书。", "biography": null, "status": "draft", "id": "d58bc9ab-d97e-592e-909f-284f788a262a"}]'::jsonb)
