INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朝廷在太庙安置五庙神主，明成祖在奉天殿受贺", "description": "永乐十九年正月初一，朝廷将五庙神主安置于太庙。明成祖朱棣在奉天殿接受朝贺，并举行宴会。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年正月甲子朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dcfdca3f-f4cd-53ce-bdaa-82a128be20e8"}, {"title": "明成祖在南郊祭祀天地", "description": "永乐十九年正月甲戌，明成祖朱棣在南郊祭祀天地。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年正月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "503ec480-a0ab-5bb7-bf82-7f54dca827f2"}, {"title": "明廷颁布大赦", "description": "永乐十九年正月戊寅，朝廷颁布大赦令。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年正月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "da7faa1a-6ef6-5417-8c4b-18934b70515b"}, {"title": "郑和再度出使西洋", "description": "永乐十九年正月癸巳，《明史》本纪记郑和再次出使西洋。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年正月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fbbf15f9-6ea0-55d2-bf43-762c5aeaaa15"}, {"title": "胡原率军巡海缉捕倭寇", "description": "永乐十九年二月辛丑，都督佥事胡原率军巡海，缉捕倭寇。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be3a421d-8c17-55ac-9dae-3083c8e6836b"}, {"title": "明廷向曾鹤龄等人授进士资格", "description": "永乐十九年三月辛巳，朝廷授予曾鹤龄等人不同等第的进士资格。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "14a76e85-ea35-5b1b-a1d9-652f54a60a9b"}, {"title": "奉天等三殿遭灾，明成祖命大臣直陈政事缺失", "description": "永乐十九年四月庚子，奉天、华盖、谨身三殿发生火灾。明成祖朱棣下诏，命群臣直言政事中的缺失。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年四月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4e8f4c1e-cee1-53a7-bf65-3248686436a7"}, {"title": "三殿遭灾后，朝廷停办扰民和非紧要事务并减免田赋", "description": "永乐十九年四月乙巳，明廷命停办给百姓造成不便及并不紧急的事务，免除永乐十七年以前积欠的赋税，并豁免上年受灾田地应缴粮税。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年四月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3acebbf6-340e-5432-b02d-4c41247cc74a"}, {"title": "明成祖因三殿遭灾取消万寿节朝贺", "description": "永乐十九年四月己酉，适逢明成祖的万寿节。因奉天等三殿遭灾，朝廷取消祝贺仪式。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4e26f3f1-7345-5600-ac6d-efdaba3ac349"}, {"title": "蹇义巡抚应天", "description": "永乐19年（年号对照1421年）四月，蹇义巡抚应天。", "start_year": 1421, "end_year": 1421, "time_original": "永乐19年（年号对照1421年）四月；公元年核为1421年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "fa20786c-daa2-5bfe-94c1-cfd706d689d8"}, {"title": "柯暹等上言后被调任地方知州", "description": "永乐十九年五月乙丑，明廷将曾上言的给事中柯暹、御史何忠、郑维桓、罗通等调出京任知州。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年五月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ccdb8e69-59b7-5dce-830c-45f605dbad45"}, {"title": "明廷命交阯屯田", "description": "永乐十九年五月庚寅，朝廷下令在交阯实行屯田。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年五月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b707051-96b6-5d62-9502-87a7c040cae9"}, {"title": "明成祖为北征安排各路将领", "description": "永乐十九年七月己巳，明成祖朱棣筹备北征，部署前锋、中军、御前骑兵、马队、左右哨和左右掖各部将领。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年七月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1e9da706-9c33-5789-83a9-1914c4835061"}, {"title": "八月初一发生日食", "description": "永乐十九年八月初一，发生日食。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年八月辛卯朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33411384-683c-57cf-b257-0c1d670d7342"}, {"title": "明廷派杨实等人核查全国各地库藏收支", "description": "永乐十九年十一月辛酉，明廷分派宦官杨实、御史戴诚等人到各地核查库藏的收支数额。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年十一月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e4ac12a-46d4-5d0b-a356-21888b05beb6"}, {"title": "夏原吉被投入监狱", "description": "永乐19年（年号对照1421年）十一月，夏原吉被投入监狱。原历日期只能确定在公元1421年至1422年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "永乐19年（年号对照1421年）十一月；发生于公元1421至1422年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e32b9744-e8ab-5c84-8e0f-eee07b1cb103"}, {"title": "吴中被投入监狱", "description": "永乐19年（年号对照1421年）十一月，吴中被投入监狱。原历日期只能确定在公元1421年至1422年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "永乐19年（年号对照1421年）十一月；发生于公元1421至1422年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "948991d4-cafb-5820-89e7-52ce910aa792"}, {"title": "方宾自缢身亡", "description": "永乐19年（年号对照1421年）十一月，方宾自缢身亡。原历日期只能确定在公元1421年至1422年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "永乐19年（年号对照1421年）十一月；发生于公元1421至1422年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "fae28aab-42fa-502c-a9fd-c13494154549"}, {"title": "侍读李时勉被下狱", "description": "永乐十九年十一月辛巳，明廷将侍读李时勉关入监狱。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年十一月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bdcc5da0-ec1f-5435-947d-9b21cef01e30"}, {"title": "明廷征调各地丁壮运粮到宣府", "description": "永乐十九年十一月甲申，朝廷征调直隶、山西、河南、山东和南畿若干府州的丁壮运粮，要求次年二月到达宣府。", "start_year": 1421, "end_year": 1421, "time_original": "永乐十九年十一月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d14c2aa1-6743-5ef9-b21a-1aeaff5d7b01"}, {"title": "瓦剌太平与把秃孛罗来朝", "description": "永乐十九年，瓦剌贤义王太平与安乐王把秃孛罗到明廷朝见。两人来朝列在本纪年末汇记。 按原历纪年，事情发生在公元1421至1422年之间。", "start_year": null, "end_year": null, "time_original": "永乐十九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9a72c23-a283-599d-81d9-06fb286c8b92"}, {"title": "本纪汇记永乐十九年多地入贡", "description": "永乐十九年，忽鲁谟斯、阿丹、祖法儿等地来贡，暹罗两次来贡。本纪在年末汇记，未开列各使到达的月日。 按原历纪年，事情发生在公元1421至1422年之间。", "start_year": null, "end_year": null, "time_original": "永乐十九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c1955dd1-5878-5b9c-bf1f-3cc2fac2de9f"}, {"title": "正月初一发生日食，朝廷取消朝贺", "description": "永乐二十年正月初一发生日食。明廷取消朝贺，命群臣检点反省。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年正月己未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "47ff012f-12cd-5fd9-a23a-bd5bb29cd5bd"}, {"title": "明成祖在南郊祭祀天地", "description": "永乐二十年正月辛未，明成祖朱棣在南郊祭祀天地。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年正月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "12e154a8-9255-5a24-abf4-e8d7f02c0ff7"}, {"title": "丰城侯李彬在交阯去世", "description": "永乐二十年正月壬申，丰城侯李彬在交阯去世。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年正月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "162f4c33-cdd3-5aec-8feb-171f583b57be"}, {"title": "李庆督办运输", "description": "永乐20年（年号对照1422年）二月，李庆督办运输。", "start_year": 1422, "end_year": 1422, "time_original": "永乐20年（年号对照1422年）二月；公元年核为1422年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "64154499-1843-5f19-a98f-4bcb22d6df86"}, {"title": "明廷命地方遇灾先救济、后报告", "description": "永乐二十年三月丙寅，朝廷下诏，主管官署遇到灾情应先施行救济，再上报朝廷。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年三月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84364413-9f28-504a-8bb4-d974b3ba2b06"}, {"title": "阿鲁台进攻兴和，都指挥王唤战死", "description": "永乐二十年三月乙亥，阿鲁台率部进攻兴和，明军都指挥王唤在交战中阵亡。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年三月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3cfa8175-ab00-54d9-92d5-7b916352137d"}, {"title": "明成祖亲征阿鲁台，皇太子监国", "description": "永乐二十年三月丁丑，明成祖朱棣决定亲自领兵征讨阿鲁台，由皇太子朱高炽监理国政。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年三月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c11b2dc2-e4b4-51a4-9ee6-6e198e4a33b1"}, {"title": "明成祖率军自京师出征", "description": "永乐二十年三月戊寅，明成祖朱棣从京师启程北征。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年三月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1d5280df-acdb-56ab-8326-b1c8bf16c9f5"}, {"title": "明军进至鸡鸣山，阿鲁台撤走", "description": "永乐二十年三月辛巳，明军到达鸡鸣山，阿鲁台撤走。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年三月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8767633d-33c2-50a4-958c-6b5f79d767f2"}, {"title": "明军行至云州，明成祖检阅军队", "description": "永乐二十年四月乙卯，明成祖朱棣领兵到云州，举行大规模阅兵。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年四月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4116945c-f856-5b3d-aadd-15ed4def5a77"}, {"title": "明成祖在偏岭打猎", "description": "永乐二十年五月乙丑，明成祖朱棣在偏岭狩猎。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年五月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "330fea3e-f89c-52b9-9b5b-c289c97dfc1d"}, {"title": "明成祖再次检阅军队", "description": "永乐二十年五月丁卯，明成祖朱棣在北征途中检阅军队。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年五月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19c90a53-9478-5951-9e09-cbc1287eaac9"}, {"title": "北征军行至西凉亭", "description": "永乐二十年五月辛未，明成祖率领的北征军到达西凉亭。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年五月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "112d652c-1b94-56ef-9c13-480e5be9d259"}, {"title": "明成祖在北征途中检阅军队", "description": "永乐二十年五月壬申，明成祖朱棣在北征途中再次检阅军队。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年五月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "deff60ac-5a8d-5365-8c5a-51ccc5c2eb6c"}, {"title": "北征军到达开平", "description": "永乐二十年五月乙酉，明成祖率领的北征军行至开平。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年五月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "291c02d6-c697-5c93-a589-fa0ff0dd1529"}, {"title": "明成祖命北征军由应昌方向继续前进", "description": "永乐二十年六月壬辰，明成祖朱棣下令北征军从应昌方向继续前进。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年六月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a42c41bf-d523-5db3-baab-61e0c1f010f2"}, {"title": "明成祖判断万全告警意在牵制，未依将领建议分兵", "description": "永乐二十年六月癸巳，探子报告阿鲁台军队进攻万全。诸将请求分兵回援，明成祖认为对方意在牵制北征军，没有采纳。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年六月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1d801a43-d1af-5b8e-8354-bf5a090784fa"}, {"title": "明军行至阳和谷，进犯万全者撤离", "description": "永乐二十年六月甲午，北征军到达阳和谷。据本纪，进犯万全的部队随后撤走。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年六月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "526ecb4c-673f-523f-9232-33c551a9b4da"}, {"title": "阿鲁台向北撤走，明军处置其遗留辎重后回师", "description": "永乐二十年七月己未，阿鲁台将辎重遗留在阔栾海旁，向北撤走。明成祖派兵烧掉遗留辎重、收走牲畜，随后回师。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年七月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e1c51aa-b1a3-5cee-b489-db898649da40"}, {"title": "明成祖在屈裂儿河击败兀良哈部众", "description": "永乐二十年七月庚午，明成祖所率明军在屈裂儿河遇到兀良哈部众并将其击败。本纪载追击三十里，杀死数十名部落首领。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年七月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b67c83e1-7a49-54f8-aa4e-38b75bec5f3f"}, {"title": "明军在河西继续进兵", "description": "永乐二十年七月辛未，明军继续进兵到河西，本纪记俘获或斩杀多人。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年七月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "817b21e0-a481-52d2-8cd1-4e897193ca8e"}, {"title": "兀良哈余部向明军投降", "description": "永乐二十年七月甲戌，兀良哈余部到明军营门请求投降。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年七月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "04cbae9d-7707-540c-a6da-52afa58d93a8"}, {"title": "皇太子豁免南北直隶等地水灾所涉粮草", "description": "永乐二十年七月，监国的皇太子朱高炽豁免南北直隶、山东、河南受水灾郡县的粮草，总数六十一万有余。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "13ad9f0b-6e5e-58ed-bed2-225e4f1915db"}, {"title": "北征各路将领报捷", "description": "永乐二十年八月戊戌，分路出兵的各位明军将领报送捷报。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年八月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "71265765-bc2c-537b-afe7-eccb3770bd64"}, {"title": "朝廷颁诏公布北征班师", "description": "永乐二十年八月辛丑，明廷向天下颁诏公布北征班师的消息。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年八月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4804e28e-ea41-5320-bb23-6f5e8661ead6"}, {"title": "郑亨与薛禄奉命戍守开平", "description": "永乐二十年八月壬寅，朝廷派武安侯郑亨和阳武侯薛禄驻守开平。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年八月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e890b0b-29f5-5e9f-838f-fa1e857e7f42"}, {"title": "郑和归来", "description": "永乐二十年八月，《明史》本纪记郑和归来。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64dcce78-c63b-5797-b13f-22f2764e8ace"}, {"title": "北征的明成祖回到京师", "description": "永乐二十年九月壬戌，北征的明成祖朱棣回到京师。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年九月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e50ed916-c629-5148-b81b-c94390157654"}, {"title": "杨士奇被关入监狱，随后获释并恢复旧职", "description": "永樂20年（1422年）九月，杨士奇被关入监狱，随后获释并恢复旧职。", "start_year": 1422, "end_year": 1422, "time_original": "永樂20年（1422年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9f402930-b30a-5709-9853-3bc3e55a3126"}, {"title": "蹇义被投入监狱", "description": "永乐20年（年号对照1422年）九月，蹇义被投入监狱。", "start_year": 1422, "end_year": 1422, "time_original": "永乐20年（年号对照1422年）九月；公元年核为1422年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6ca4ecaa-8da7-5c68-905e-620ccbd46e18"}, {"title": "吕震被投入监狱", "description": "永乐20年（年号对照1422年）九月，吕震被投入监狱。", "start_year": 1422, "end_year": 1422, "time_original": "永乐20年（年号对照1422年）九月；公元年核为1422年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "807a6c04-05b4-518c-8033-6ed8003c2c48"}, {"title": "明廷论北征战功，封朱荣为武进伯、薛贵为安顺伯", "description": "永乐二十年九月辛未，朝廷评定随征功劳，封左都督朱荣为武进伯，封都督佥事薛贵为安顺伯。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年九月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1fb75070-9e8e-5472-8afb-985c15e9b28a"}, {"title": "明廷派八十名官员核查各地仓粮收支", "description": "永乐二十年十月癸巳，明廷分派宦官及朝臣共八十人到各地核查仓粮收支数额。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年十月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "59404c75-aaa6-5795-b4f9-3ba3f693e119"}, {"title": "朱荣奉命镇守辽东", "description": "永乐二十年十二月辛卯，朝廷派朱荣镇守辽东。", "start_year": 1422, "end_year": 1422, "time_original": "永乐二十年十二月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0162c5f5-6a14-5df6-afdd-005ed3dd8a98"}, {"title": "乾清宫发生火灾", "description": "永乐二十年闰十二月戊寅，乾清宫发生火灾。按干支换算，已在公元1423年。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十年闰十二月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f0222da-7048-5def-9acb-5390e149e876"}, {"title": "本纪汇记永乐二十年多地进贡", "description": "永乐二十年，暹罗、苏门答剌、阿丹等地有进献地方物产的记载，占城、琉球中山、卜花儿、哈密、瓦剌、土鲁番和爪哇也有入贡记录。 按原历纪年，事情发生在公元1422至1423年之间。", "start_year": null, "end_year": null, "time_original": "永乐二十年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "966fd1b9-fd9f-54e4-8b5f-b958eff498f1"}]'::jsonb)
